-- Global exercise catalog (FR-009): exercises are the same for every trainer, so the common ones live
-- once, without a holder, and every trainer reads them. A trainer only adds an exercise of their own
-- when its name is in neither the global catalog nor theirs. Existing exercises stay as their trainer's own.
ALTER TABLE planning.exercises ALTER COLUMN holder_id DROP NOT NULL;

-- (holder_id, name) stays unique for own exercises; NULL holders need their own unique index.
CREATE UNIQUE INDEX IF NOT EXISTS uq_exercises_global_name
    ON planning.exercises (lower(name)) WHERE holder_id IS NULL;

ON CONFLICT DO NOTHING;
